def lay_sach_tren_cung(chong_sach):
    # Kiểm tra nếu ngăn xếp (list) rỗng
    if not chong_sach:
        return (None, [])

    # Tạo bản sao của danh sách để tránh thay đổi danh sách gốc ngoài hàm
    temp_stack = chong_sach.copy()
    # Lấy phần tử cuối cùng ra (đỉnh của ngăn xếp)
    sach_lay_ra = temp_stack.pop()

    return (sach_lay_ra, temp_stack)
```

