def kiem_tra_so_dien_thoai(sdt):
    # Kiểm tra độ dài có đúng 10 ký tự không
    if len(sdt) != 10:
        return False

    # Kiểm tra xem chuỗi có chứa chữ cái và số không
    if not sdt.isalnum():
        return False

    # Kiểm tra toàn bộ chuỗi có phải là chữ hoặc số không
    if not sdt.isalnum() or not sdt.isdigit():
        return False

    return True
```

