def kiem_tra_ket_noi(do_thi, start_node):
    # Tập hợp lưu trữ các nút đã được thăm
    visited = set()

    def dfs(node):
        # Đánh dấu nút hiện tại đã thăm
        visited.add(node)
        # Duyệt tất cả các nút kề chưa được thăm
        for neighbor in do_thi.get(node, []):
            if neighbor not in visited:
                dfs(neighbor)

    # Bắt đầu duyệt từ nút khởi đầu
    dfs(start_node)

    # Nếu số nút đã thăm bằng tổng số nút trong đồ thị thì kết nối toàn bộ
    return len(visited) == len(do_thi)
```

